using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Inventory;
using BARANG.Core.Domain.Organization;
using BARANG.Core.Infrastructure.Persistence;
using Xunit;

namespace BARANG.Core.IntegrationTests.Database;

[Collection(PostgreSqlDatabaseFixture.CollectionName)]
public sealed class Step4InventoryIssueE2ETests(PostgreSqlDatabaseFixture database)
{
    [Fact]
    public async Task WarehouseIssueIsAtomicAndRetrySafeWithoutDuplicatingLedgerEntries()
    {
        await database.ResetAsync(TestContext.Current.CancellationToken);
        Guid company=Guid.NewGuid(), branch=Guid.NewGuid(), customer=Guid.NewGuid(), warehouseId=Guid.NewGuid(); DateTimeOffset now=DateTimeOffset.UtcNow;
        Product product; ProductVariant variant;
        await using(CoreDbContext db=database.CreateAdministrationCoreDbContext())
        {
            db.Companies.Add(Company.Create(company,"STEP4_ISSUE","STEP4 issue",now).Value);db.Branches.Add(Branch.Create(branch,company,"MAIN","Main",now).Value);db.Customers.Add(Customer.Create(customer,company,"C-4",CustomerType.Organization,null,null,null,"Step4 Customer",null,null,null,null,null,null,null,now).Value);product=Product.Create(Guid.NewGuid(),company,"P-4","Step4 Product",null,"RAW","PCS",now).Value;variant=ProductVariant.Create(Guid.NewGuid(),product,"SKU-4","Step4",null,null,null,now).Value;db.Products.Add(product);db.ProductVariants.Add(variant);db.Warehouses.Add(Warehouse.Create(warehouseId,company,branch,"W4","Step4 Warehouse",WarehouseType.RawMaterials,now).Value);await db.SaveChangesAsync(TestContext.Current.CancellationToken);
            StockBalance balance=StockBalance.Create(company,warehouseId,variant.Id,now);Assert.True(balance.ApplyOnHand(10,false,now).IsSuccess);db.StockBalances.Add(balance);await db.SaveChangesAsync(TestContext.Current.CancellationToken);
        }
        await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient client=factory.CreateClient();using HttpRequestMessage bootstrap=new(HttpMethod.Post,"/api/v1/security/bootstrap"){Content=JsonContent.Create(new{companyId=company,username="step4-admin",displayName="STEP4 Admin",password="StrongStep4Password123"})};bootstrap.Headers.Add("X-Bootstrap-Secret","test-bootstrap-secret-123456789");(await client.SendAsync(bootstrap,TestContext.Current.CancellationToken)).EnsureSuccessStatusCode();await WorkflowTestData.SeedPublishedOrderDefinitionAsync(database.ConnectionString,company,"step4-admin",TestContext.Current.CancellationToken);Login login=(await(await client.PostAsJsonAsync("/api/v1/auth/login",new{username="step4-admin",password="StrongStep4Password123"},TestContext.Current.CancellationToken)).Content.ReadFromJsonAsync<Login>(TestContext.Current.CancellationToken))!;await Send<object>(client,Req(HttpMethod.Post,"/api/v1/auth/me/company",login.AccessToken,null,new{companyId=company}));
        OrderView draft=await Send<OrderView>(client,Req(HttpMethod.Post,"/api/v1/orders",login.AccessToken,company,new{branchId=branch,customerId=customer,source="Internal",orderDate="2026-10-14"}));OrderItemView first=await Send<OrderItemView>(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items",login.AccessToken,company,new{productId=product.Id,productVariantId=variant.Id,quantity=2}));await Send<OrderItemView>(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items",login.AccessToken,company,new{productId=product.Id,productVariantId=variant.Id,quantity=3}));draft=await Send<OrderView>(client,Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}",login.AccessToken,company));OrderView submitted=await Send<OrderView>(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/submit",login.AccessToken,company,new{version=draft.Version}));
        ReservationResult reserved=await Send<ReservationResult>(client,Req(HttpMethod.Post,$"/api/v1/inventory/orders/{submitted.Id}/reservations",login.AccessToken,company,new{warehouseId,idempotencyKey=$"step4:{submitted.Id:N}"}));Assert.Equal(2,reserved.Reservations.Length);
        IssueResult issued=await Send<IssueResult>(client,Req(HttpMethod.Post,$"/api/v1/inventory/orders/{submitted.Id}/issues",login.AccessToken,company,new{warehouseId,reference=$"STEP4-ISSUE-{submitted.Id:N}",items=reserved.Reservations.Select(x=>new{orderItemId=x.OrderItemId,quantity=x.RemainingQuantity,uomCode=x.UomCode}).ToArray()}));Assert.Equal(2,issued.Transactions.Length);Assert.All(issued.Reservations,x=>Assert.Equal(0,x.RemainingQuantity));
        IssueResult retry=await Send<IssueResult>(client,Req(HttpMethod.Post,$"/api/v1/inventory/orders/{submitted.Id}/issues",login.AccessToken,company,new{warehouseId,reference=$"STEP4-ISSUE-{submitted.Id:N}",items=reserved.Reservations.Select(x=>new{orderItemId=x.OrderItemId,quantity=x.RequestedQuantity,uomCode=x.UomCode}).ToArray()}));Assert.Equal(2,retry.Transactions.Length);
        Balance[] balances=await Send<Balance[]>(client,Req(HttpMethod.Get,$"/api/v1/inventory/balances?warehouseId={warehouseId}&variantId={variant.Id}",login.AccessToken,company));Assert.Single(balances);Assert.Equal(5,balances[0].OnHand);Assert.Equal(0,balances[0].Reserved);
        using(HttpResponseMessage changed=await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/inventory/orders/{submitted.Id}/issues",login.AccessToken,company,new{warehouseId,reference=$"STEP4-ISSUE-{submitted.Id:N}",items=new[]{new{orderItemId=first.Id,quantity=1,uomCode="PCS"}}}),TestContext.Current.CancellationToken))Assert.Equal(HttpStatusCode.Conflict,changed.StatusCode);
        OrderView cancelDraft=await Send<OrderView>(client,Req(HttpMethod.Post,"/api/v1/orders",login.AccessToken,company,new{branchId=branch,customerId=customer,source="Internal",orderDate="2026-10-14"}));await Send<OrderItemView>(client,Req(HttpMethod.Post,$"/api/v1/orders/{cancelDraft.Id}/items",login.AccessToken,company,new{productId=product.Id,productVariantId=variant.Id,quantity=1}));cancelDraft=await Send<OrderView>(client,Req(HttpMethod.Get,$"/api/v1/orders/{cancelDraft.Id}",login.AccessToken,company));OrderView cancelSubmitted=await Send<OrderView>(client,Req(HttpMethod.Post,$"/api/v1/orders/{cancelDraft.Id}/submit",login.AccessToken,company,new{version=cancelDraft.Version}));ReservationResult cancelReservation=await Send<ReservationResult>(client,Req(HttpMethod.Post,$"/api/v1/inventory/orders/{cancelSubmitted.Id}/reservations",login.AccessToken,company,new{warehouseId,idempotencyKey=$"step4-cancel:{cancelSubmitted.Id:N}"}));Assert.Single(cancelReservation.Reservations);await Send<OrderView>(client,Req(HttpMethod.Post,$"/api/v1/orders/{cancelSubmitted.Id}/cancel",login.AccessToken,company,new{version=cancelSubmitted.Version,reasonCode="STEP4_TEST",reasonText="isolated test"}));balances=await Send<Balance[]>(client,Req(HttpMethod.Get,$"/api/v1/inventory/balances?warehouseId={warehouseId}&variantId={variant.Id}",login.AccessToken,company));Assert.Equal(5,balances.Single().OnHand);Assert.Equal(0,balances.Single().Reserved);
    }
    private static HttpRequestMessage Req(HttpMethod method,string uri,string token,Guid?company,object?body=null){HttpRequestMessage r=new(method,uri);r.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);if(company is not null)r.Headers.Add("X-Company-ID",company.ToString());if(body is not null)r.Content=JsonContent.Create(body);return r;}
    private static async Task<T> Send<T>(HttpClient client,HttpRequestMessage request){using HttpResponseMessage response=await client.SendAsync(request,TestContext.Current.CancellationToken);string payload=await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken);Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {payload}");return typeof(T)==typeof(object)?(T)(object)new(): (await response.Content.ReadFromJsonAsync<T>(TestContext.Current.CancellationToken))!;}
    private sealed record Login(string AccessToken);private sealed record OrderView(Guid Id,long Version);private sealed record OrderItemView(Guid Id);private sealed record ReservationResult(Reservation[] Reservations);private sealed record Reservation(Guid OrderItemId,string UomCode,decimal RequestedQuantity,decimal RemainingQuantity);private sealed record IssueResult(Reservation[] Reservations,Transaction[] Transactions);private sealed record Transaction(Guid Id);private sealed record Balance(Guid WarehouseId,Guid ProductVariantId,decimal OnHand,decimal Reserved,decimal Available,long Version);
}
